  const output = execFileSync('npm', ['run', '--silent', 'read', '--', input], { encoding: 'utf8' });
  assert.equal(JSON.parse(output), expected, input);
  console.log(input, '->', output.trim());
}
assert.equal(forDisplay('12.50'), '12.50');
assert.equal(forDisplay(0), '0.00');
assert.equal(forDisplay(null), '—');
console.log('forDisplay: decimal, zero, missing OK');
JS"

